func jobTone(state string) view.Tone {
	switch state {
	case "done":
		return view.OK
	case "running", "queued":
		return view.Accent
	case "failed":
		return view.Bad
	}
	return view.Neutral
}

func itemTone(state string) view.Tone {
	switch state {
	case "done":
		return view.OK
	case "running":
		return view.Accent
	case "waiting":
		return view.Neutral
	case "refused":
		return view.Bad
	}
	return view.Warn
}

